import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Çerçeve, fotoğrafı tamamlar. İnce bir çizgi bile görseli öne çıkarır ve sayfada düzenli gösterir.</p>\n<p>Doğru çerçeve, fotoğrafı yüceltir. Yanlış çerçeve ise görseli boğar ve dikkati dağıtır.</p>\n<p>Bu kılavuz, düz çerçeveleri, Polaroid stilini ve degrade parıltıyı, ayrıca boyut, köşe yarıçapı ve gölge ayarlarını anlatıyor.</p>\n<h2 id=\"what-is-a-border\">Görsel çerçevesi nedir?</h2>\n<p>Çerçeve, görselin etrafına eklenen renkli ya da desenli banttır. Fotoğrafı sayfadan ayırır.</p>\n<p>Çerçeveler yüzyıllardır kullanılır. Tablolar çerçevelenir; fotoğraflar da aynı geleneği izler.</p>\n<p>Dijital çerçeve, fotoğrafın parçası olur. Dışa aktarıldıktan sonra çerçeve, görselle birlikte kaydedilir.</p>\n<h2 id=\"solid-borders\">Düz çerçeveler: klasik çerçeve</h2>\n<p>Düz çerçeve, tek renkli banttır. Beyaz çerçeve, fotoğrafı temiz gösterir.</p>\n<p>Siyah çerçeve, dramatik görünür. Galeri ve portrelerde siyah çerçeve yaygındır.</p>\n<p>Düz çerçeve, her fotoğrafta işe yarar. Güvenli ve zamansız bir seçimdir.</p>\n<h2 id=\"polaroid-style\">Polaroid stili: retro favori</h2>\n<p>Polaroid çerçevesi için araçta alt bandı geniş tutun; o beyaz alana tarih veya kısa bir not yazabilirsiniz.</p>\n<p>Araçtaki bu çerçeveyle anı fotoğraflarına nostaljik bir hava katın; davetiye ve albüm karelerinde özellikle güzel durur.</p>\n<p>Araçta Polaroid çerçeveyi kare fotoğraflara uygulayın; dikey karelerde de işe yarar ama karede etkisi daha güçlüdür.</p>\n<h2 id=\"gradient-glow\">Degrade parıltılı çerçeveler</h2>\n<p>Araçta degrade çerçeveyi seçerseniz renkler yumuşakça birbirine geçer; bu geçiş, kareye çağdaş bir parlaklık katar.</p>\n<p>Genç kitleye ulaşan gönderilerde bu çerçeveyi deneyin; araçta bir tıkla uygulanır ve akışta modern durur.</p>\n<p>Degrade çerçeveyi ayarlarken renkleri yumuşak tutun; çok güçlü bir geçiş, araçta bile fotoğrafı geri plana iter.</p>\n<h2 id=\"border-size\">Çerçeve boyutu: yüzde 1'den yüzde 25'e</h2>\n<p>Çerçeve boyutu, fotoğraf boyutunun yüzdesi olarak ayarlanır. Yüzde 1-2, ince bir çizgidir.</p>\n<p>Yüzde 5-10, belirgin bir çerçevedir. Çoğu kullanımda bu aralık yeterlidir.</p>\n<p>Yüzde 25, kalın bir çerçevedir. Polaroid stilinde alt bant bu kadar geniş olabilir.</p>\n<h2 id=\"frame-radius-vs-photo-radius\">Çerçeve yarıçapı ve fotoğraf yarıçapı</h2>\n<p>Çerçeve yarıçapı, dış köşeleri yuvarlar. Fotoğraf yarıçapı, iç köşeleri yuvarlar.</p>\n<p>İkisini birlikte ayarlayın. Dış ve iç yarıçap uyumlu olmalıdır.</p>\n<p>Yuvarlak köşeler, modern görünür. Keskin köşeler, klasik görünür.</p>\n<h2 id=\"drop-shadows\">Gölgeler: derinlik eklemek</h2>\n<p>Gölge, çerçeveye derinlik verir. Fotoğraf, sayfadan yükselmiş gibi görünür.</p>\n<p>Hafif gölge kullanın. Koyu gölge, görseli ağır gösterir.</p>\n<p>Gölge, JPG'ye aktarılırken kaybolabilir. Saydamlık gerekiyorsa PNG kullanın.</p>\n<h2 id=\"colour-choices\">Çerçeve renkleri seçmek</h2>\n<p>Araçta beyaz çerçeveyi varsayılan olarak deneyin; her fotoğrafta temiz durur ve yanlış seçim riskini ortadan kaldırır.</p>\n<p>Siyah çerçeve, dramatik görünür. Portre ve galeri fotoğraflarında kullanılır.</p>\n<p>Fotoğraftaki bir rengi seçin. Çerçeve, fotoğrafla uyumlu olmalıdır.</p>\n<h2 id=\"quick-frame-presets\">Hızlı çerçeve ön ayarları</h2>\n<p>Araçtaki hazır ön ayarlarla başlayın; beyaz, siyah ve Polaroid çerçeveler tek dokunuşla uygulanır.</p>\n<p>Araçta önce bir ön ayar seçin, sonra rengini değiştirin; ön ayar, çerçevenin taslağıdır, son hâli siz belirlersiniz.</p>\n<p>Araçta sık kullandığınız çerçeveyi ön ayarlara kaydedin; tekrarlayan işlerde her seferinde sıfırdan ayar yapmazsınız.</p>\n<h2 id=\"borders-for-social\">Sosyal medya için çerçeveler</h2>\n<p>Gönderinize araçta beyaz çerçeve ekleyin; kalabalık akışta kare, çerçevesiyle birlikte gözden kaçmaz.</p>\n<p>Araçta çerçeve kalınlığını ince ayarlayın; kalın bir çerçeve, telefon ekranında fotoğrafı iyice küçültür.</p>\n<p>Araçta bir çerçeve stili seçip tüm gönderilerinizde onu kullanın; tekrar eden çerçeve, profilinizi tanınır yapar.</p>\n<h2 id=\"borders-for-print\">Baskı için çerçeveler</h2>\n<p>Baskıda çerçeve, fotoğrafın parçasıdır. Beyaz kenar, baskıda zarif görünür.</p>\n<p>İndirmeden önce çerçevenin baskı boyutuyla uyuştuğunu önizlemede doğrulayın; kenar payı hatalıysa baskıda çerçeve kırpılır.</p>\n<p>Çerçeveyi eklemeden önce baskı merkezinize danışın; kenar payı ve kesim payı konusunda ne istediklerini öğrenin, sonra aracı ona göre ayarlayın.</p>\n<h2 id=\"borders-for-products\">Ürün fotoğrafları için çerçeveler</h2>\n<p>Ürün fotoğrafına araçta sade bir çerçeve ekleyin; beyaz çerçeve, dikkati dağıtmadan ürünü öne çıkarır.</p>\n<p>Mağaza görsellerinizi araçta hep aynı çerçeveyle hazırlayın; tek tip çerçeve, ürün listenizi düzenli ve profesyonel gösterir.</p>\n<p>Ürün görselinde araçta ince çerçeve kullanın; kalın çerçeve, ürünün ekrandaki payını azaltır.</p>\n<h2 id=\"transparency-and-formats\">Saydamlık, formatlar ve dışa aktarma</h2>\n<p>Saydam köşeler için PNG kullanın. JPG saydamlığı desteklemez; köşeler beyaz dolar.</p>\n<p>Gölge için PNG kullanın. JPG, yumuşak gölgeyi sert gösterir.</p>\n<p>Çerçeveli fotoğraflar için JPG kullanın. Dosya küçüktür ve her yerde açılır.</p>\n<h2 id=\"borders-vs-frames-vs-matting\">Çerçeve, çerçeve ve paspartu: fark nedir?</h2>\n<p>Çerçeve, görselin kenarındaki banttır. Paspartu, fotoğraf ile çerçeve arasındaki boşluktur.</p>\n<p>Dijitalde ikisi benzer görünür. Geniş beyaz bant, paspartu etkisi verir.</p>\n<p>Seçim, tarza bağlıdır. Sade görünüm için çerçeve, galeri görünümü için paspartu kullanın.</p>\n<h2 id=\"privacy-local-processing\">Gizlilik: hiçbir şey yüklemeden çerçevelemek</h2>\n<p>Çerçeve aracı tamamen tarayıcıda çalışır. Fotoğraflarınız sunucuya yüklenmez.</p>\n<p>Özel fotoğraflarda bu güvence önemlidir. Aile ve müşteri görsellerini rahatça çerçeveleyebilirsiniz.</p>\n<p>Sayfayı kapattığınızda veriler yok olur. Fotoğraflarınız cihazınızda kalır.</p>\n<h2 id=\"common-border-mistakes\">Çerçevelerle yaygın hatalar</h2>\n<p>En yaygın hata, çok kalın çerçevedir. Kalın çerçeve, fotoğrafı küçültür ve boğar.</p>\n<p>Bir başka hata, uyumsuz renktir. Çerçeve, fotoğrafla çatışmamalıdır.</p>\n<p>Üçüncü hata, tutarsızlıktır. Her fotoğrafta farklı çerçeve, profili dağınık gösterir.</p>\n<p>Özetle: çerçeve fotoğrafı tamamlamalı, boğmamalıdır. Adımlar için <a href=\"/tr/blog/gorsele-cerceve-nasil-eklenir\">Görsele çerçeve nasıl eklenir</a> yazısına bakın; stiller için <a href=\"/tr/blog/gorsel-cerceve-kenarlik-stilleri\">görsel çerçeve ve kenar stilleri</a> yazısı yardımcı olur. Köşeler için <a href=\"/tr/gorsel-kose-yuvarla\">köşe yuvarlama</a> hazırdır; araç ise <a href=\"/tr/gorsel-cerceve-olusturucu\">görsel çerçeve oluşturucu</a> sayfasındadır.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Bir fotoğraf için en iyi çerçeve rengi hangisi?","answer":"Beyaz en güvenli seçimdir; her fotoğrafta temiz görünür. Siyah, portre ve galeri fotoğraflarında dramatik durur. Fotoğraftaki bir rengi seçmek de uyumlu görünür; çerçeve fotoğrafla çatışmamalıdır."},{"question":"Çerçeve eklemek görselimin boyutunu değiştirir mi?","answer":"Evet, çerçeve görselin dışına eklenir; toplam boyut büyür. Yüzde 5 çerçeve, görseli her yönde yüzde 5 büyütür. Hedef boyut sabitse çerçeveyi hesaba katın."},{"question":"Gölgem JPG olarak dışa aktardıktan sonra neden kayboldu?","answer":"Çünkü JPG saydamlığı desteklemez; yumuşak gölge sertleşir ya da beyazla dolar. Gölge ve saydam köşeler için PNG kullanın. Fotoğraflar için JPG, saydamlık için PNG kuralı işler."},{"question":"Polaroid çerçeve ile düz çerçeve arasındaki fark nedir?","answer":"Polaroid çerçevesi altta geniş beyaz bant ister; alt banda yazı yazılabilir ve retro his verir. Düz çerçeve her kenarda eşit bant kullanır; klasik ve sade görünür. Polaroid kare fotoğraflarda en iyi görünür."},{"question":"Telefonda bir fotoğrafa çerçeve ekleyebilir miyim?","answer":"Evet. Çerçeve aracını telefon tarayıcısında açın, fotoğrafı yükleyin ve stili seçin. İndirilen dosya İndirilenler klasörüne gider. Hassas ayarlar için bilgisayarı tercih edin."},{"question":"Ürün fotoğraflarında çerçeve olmalı mı?","answer":"İnce ve sade çerçeve olabilir; kalın çerçeve ürünü küçültür. Tüm ürün görsellerinde aynı çerçeveyi kullanın; tutarlı liste mağazada profesyonel görünür. Beyaz çerçeve, ürünü öne çıkarır."}];
